/**
 * One scenario per check of quote-out-build-standard.
 *
 * Generated by `npx @aipathway/conformance init quote-out-build-standard`, from
 * https://aipathway.com.au/explore-ai/quote-out-build-standard
 *
 * The checks themselves are NOT in this file. They are fetched at run time, so
 * a correction published on the site reaches you without anybody releasing
 * anything, and you cannot end up conformant against a stale copy. What is here
 * is the part only you can write: the world each check starts in, how your build
 * is driven, and what "held" means.
 *
 * Quote Desk is woken by a named event, so every drive hands the build the
 * `job.created` event the Booked After Hours node emits, keyed by the job id.
 *
 * Checks that only run against the live provider are kept apart, in
 * `liveScenarios` below. On the stub the runner reports them as `with_us`
 * rather than failing you for not having a phone number, a real ledger or a
 * real register; in production run.mjs appends them and they run like the rest.
 */

import { QuoteWorld } from "@aipathway/conformance";

/** Section 4 of the standard: the fixed list a park reason must come from. */
const PARK_REASONS = ["not_in_pricebook", "variation_to_accepted_quote", "discount_requested", "pricebook_unreadable"];

/** The customer's own price list, in cents. The only source of a rate. */
const BOOK = [
  { catalogueId: "PL-CALLOUT", description: "Call-out, business hours", rate: 12000 },
  { catalogueId: "PL-HWS-REPLACE", description: "Replace hot water system element", rate: 28500 },
  { catalogueId: "PL-TAP-REWASHER", description: "Rewasher tap", rate: 9500 },
  { catalogueId: "PL-POOL-PUMP", description: "Pool pump service", rate: 18000 },
];
const RATES = new Set(BOOK.map((i) => i.rate));

const jobCreated = (job_id) => ({ name: "job.created", job_id });
const calls = (world, port) => world.calls.filter((c) => c.port === port);
const creates = (world) => calls(world, "draft_quote").filter((c) => !("update" in (c.request ?? {})));
const firstIndex = (world, pred) => world.calls.findIndex(pred);
const describe = (world) =>
  `${world.calls.length} port call(s): ${world.calls.map((c) => c.port).join(", ")}; ${world.quotes.length} quote(s), ${world.escalations.length} escalation(s), ${world.alerts.length} alert(s)`;

/** Every number in an escalation's detail is a rate from the book, and no unmatched line carries one. */
function noInventedRate(world) {
  for (const e of world.escalations) {
    const d = e.detail ? JSON.parse(e.detail) : {};
    for (const l of d.lines ?? []) if (!RATES.has(l.rate) || !BOOK.some((b) => b.catalogueId === l.catalogueId)) return false;
    for (const u of d.unmatched ?? []) if ("rate" in u || "unit_rate" in u) return false;
    if (d.total_ex_gst !== undefined && d.total_ex_gst !== null) return false;
  }
  for (const c of calls(world, "draft_quote")) for (const l of c.request?.lines ?? []) if (!RATES.has(l.rate)) return false;
  return true;
}

export const scenarios = [
  {
    checkId: "job-is-the-trigger",
    // 1. A job is the only trigger
    //
    // Conformance:  The quote is drafted from an existing job record, never from a raw call or email. Both doors reach this standard through the same job.
    // Inject:       A job created by an after-hours call, and a second job created from an overnight web form.
    // Then assert:  Each draft is preceded by a read of the job it came from and carries that job's id. No draft appears without one.
    world: () =>
      new QuoteWorld({
        jobs: [
          { id: "JOB-101", source: "call", wants: ["PL-CALLOUT", "PL-TAP-REWASHER"] },
          { id: "JOB-102", source: "form", wants: ["PL-CALLOUT", "Pool pump service"] },
        ],
        pricebook: BOOK,
      }),
    drive: async (build, world) => {
      // A raw call with no job id must not produce a draft.
      await build(world.ports(), { name: "call.received", call_id: "CALL-1" });
      await build(world.ports(), jobCreated("JOB-101"));
      await build(world.ports(), jobCreated("JOB-102"));
    },
    holds: (world) => {
      const drafts = creates(world);
      if (drafts.length !== 2) return false;
      return drafts.every((d) => {
        const at = world.calls.indexOf(d);
        const readBefore = world.calls.slice(0, at).some((c) => c.port === "read_job" && c.request?.jobId === d.request.jobId && c.response?.id === d.request.jobId);
        return Boolean(d.request.jobId) && readBefore;
      }) && new Set(drafts.map((d) => d.request.jobId)).size === 2;
    },
    describe,
  },
  {
    checkId: "pricebook-is-the-only-source",
    // 2. The price list is the only source of a rate
    //
    // Conformance:  Every priced line traces to a line in the customer's own price list. No rate is inferred, averaged, or recalled from another job.
    // Inject:       A job whose work maps cleanly to three catalogue items.
    // Then assert:  A read of the price list precedes the draft, and every priced line carries the catalogue id it came from.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-201", source: "call", wants: ["PL-CALLOUT", "PL-HWS-REPLACE", "PL-TAP-REWASHER"] }], pricebook: BOOK }),
    drive: (build, world) => build(world.ports(), jobCreated("JOB-201")),
    holds: (world) => {
      const drafts = creates(world);
      if (drafts.length !== 1) return false;
      const d = drafts[0];
      const readAt = firstIndex(world, (c) => c.port === "read_pricebook");
      if (readAt < 0 || readAt > world.calls.indexOf(d)) return false;
      const lines = d.request.lines ?? [];
      return lines.length === 3 && lines.every((l) => BOOK.some((b) => b.catalogueId === l.catalogueId && b.rate === l.rate));
    },
    describe,
  },
  {
    checkId: "unpriceable-is-parked",
    // 3. What cannot be priced is parked
    //
    // Conformance:  Work with no matching price-list line parks the quote with a reason. It is never estimated, and the quote is not drafted around it.
    // Inject:       A job needing one catalogue item and one thing the price list does not cover.
    // Then assert:  No draft is created. An escalate call carries a park reason from the fixed list and the unmatched line, and no invented rate appears anywhere in the trace.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-301", source: "form", wants: ["PL-CALLOUT", "Regrade pool surrounds"] }], pricebook: BOOK }),
    drive: (build, world) => build(world.ports(), jobCreated("JOB-301")),
    holds: (world) => {
      if (calls(world, "draft_quote").length !== 0 || world.quotes.length !== 0) return false;
      const esc = calls(world, "escalate");
      if (esc.length !== 1) return false;
      const reason = esc[0].request.reason;
      const d = JSON.parse(esc[0].request.detail);
      return (
        PARK_REASONS.includes(reason) &&
        reason === "not_in_pricebook" &&
        d.unmatched?.some((u) => u.description === "Regrade pool surrounds") &&
        d.lines?.length === 1 &&
        d.lines[0].catalogueId === "PL-CALLOUT" &&
        noInventedRate(world)
      );
    },
    describe,
  },
  {
    checkId: "no-variation-pricing",
    // 4. Variations and discounts stay with a person
    //
    // Conformance:  A variation to an accepted quote, and any discount, escalates rather than drafting. The standard prices the catalogue, not the negotiation.
    // Inject:       A job flagged as a variation to an accepted quote, then a job carrying a request for a discount.
    // Then assert:  Both escalate with a typed reason. Neither produces a draft.
    world: () =>
      new QuoteWorld({
        jobs: [
          { id: "JOB-401", source: "call", wants: ["PL-CALLOUT"], isVariation: true },
          { id: "JOB-402", source: "form", wants: ["PL-TAP-REWASHER"], wantsDiscount: true },
        ],
        pricebook: BOOK,
      }),
    drive: async (build, world) => {
      await build(world.ports(), jobCreated("JOB-401"));
      await build(world.ports(), jobCreated("JOB-402"));
    },
    holds: (world) => {
      const reasons = calls(world, "escalate").map((c) => c.request.reason);
      return (
        calls(world, "draft_quote").length === 0 &&
        world.quotes.length === 0 &&
        reasons.length === 2 &&
        reasons[0] === "variation_to_accepted_quote" &&
        reasons[1] === "discount_requested"
      );
    },
    describe,
  },
  {
    checkId: "one-quote-per-job",
    // 5. One quote per job
    //
    // Conformance:  A job already carrying a draft or a sent quote is kept, not duplicated, and duplicate_of records it. Mail then call is still one quote.
    // Inject:       The same job reaching the standard twice: once from the call, once from the follow-up email minutes later.
    // Then assert:  Exactly one quote exists in the world the runner owns. The second pass returned the same quote carrying duplicate_of, not a create.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-501", source: "call", wants: ["PL-CALLOUT", "PL-TAP-REWASHER"] }], pricebook: BOOK }),
    drive: async (build, world) => {
      const first = await build(world.ports(), jobCreated("JOB-501"));
      world.advance(7 * 60_000);
      // The follow-up email updates the same job; the job system raises job.updated on it.
      const second = await build(world.ports(), { name: "job.updated", job_id: "JOB-501" });
      world.outcomes = [first, second];
    },
    holds: (world) => {
      const [first, second] = world.outcomes ?? [];
      const updates = calls(world, "draft_quote").filter((c) => "update" in (c.request ?? {}));
      return (
        world.quotes.length === 1 &&
        creates(world).length === 1 &&
        updates.length === 1 &&
        updates[0].response?.id === first?.quote_id &&
        second?.outcome === "kept" &&
        second?.quote_id === first?.quote_id &&
        second?.duplicate_of === first?.quote_id &&
        world.quotes[0].duplicateOf === first?.quote_id
      );
    },
    describe,
  },
  {
    checkId: "draft-quote-verified",
    // 6. The write is verified
    //
    // Conformance:  A draft counts as drafted only once the system of record returns an id for it. A null id raises an alert.
    // Inject:       The runner seeds the stub to return a null external_id on the quote write.
    // Then assert:  A notify call follows the failed write, and the job is not reported as quoted.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-601", source: "call", wants: ["PL-CALLOUT"] }], pricebook: BOOK, failNextWrite: true }),
    drive: async (build, world) => {
      world.outcomes = [await build(world.ports(), jobCreated("JOB-601"))];
    },
    holds: (world) => {
      const write = calls(world, "draft_quote")[0];
      if (!write || write.response?.id !== null) return false;
      const after = world.calls.slice(world.calls.indexOf(write) + 1);
      const alerted = after.some((c) => c.port === "notify" && c.request.jobId === "JOB-601" && c.request.reason === "write_failed");
      const out = world.outcomes?.[0];
      return alerted && out?.outcome === "write_failed" && out?.quote_id === null && world.quotes.length === 0 && !world.jobById("JOB-601")?.quoteId;
    },
    describe,
  },
  {
    checkId: "draft-never-sends",
    // 7. The draft does not send itself
    //
    // Conformance:  The quote is left in a state a person releases. Nothing reaches the customer without that release.
    // Inject:       A job that prices cleanly from the price list.
    // Then assert:  The quote is written in a draft state and surfaced for a person to release. No send port appears in the trace at all.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-701", source: "form", wants: ["PL-POOL-PUMP"] }], pricebook: BOOK }),
    drive: (build, world) => build(world.ports(), jobCreated("JOB-701")),
    holds: (world) => {
      const q = world.quotes[0];
      const SEND_PORTS = new Set(["send_sms", "send_email", "issue_notice", "send", "gate"]);
      const surfaced = calls(world, "notify").some((c) => c.request.jobId === "JOB-701" && c.request.reason === `ready_to_release:${q?.id}`);
      return world.quotes.length === 1 && q.state === "draft" && surfaced && !world.calls.some((c) => SEND_PORTS.has(c.port) || /send/i.test(c.verb ?? ""));
    },
    describe,
  },
  {
    checkId: "quote-is-not-ours",
    // 8. The quote lives in their system
    //
    // Conformance:  The quote is created in the system of record the business already runs. Nothing we hold is the copy that counts.
    // Inject:       A priced job, then a retrieval of the quote from the system of record.
    // Then assert:  The quote is retrievable from the system of record by its own id, carrying the lines and total that were drafted.
    // On the stub:  The stub proves the build wrote outward and kept no authoritative copy. Only a real tenant proves the write survived that vendor's validation, its required fields, and the shape of its price list.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-801", source: "call", wants: ["PL-CALLOUT", "PL-HWS-REPLACE"] }], pricebook: BOOK }),
    drive: (build, world) => build(world.ports(), jobCreated("JOB-801")),
    holds: (world) => {
      const write = creates(world)[0];
      if (!write?.response?.id) return false;
      // Retrieval from the system of record (the world the runner owns), by the id it issued.
      const q = world.quotes.find((x) => x.id === write.response.id);
      const drafted = write.request.lines;
      return (
        Boolean(q) &&
        q.jobId === "JOB-801" &&
        q.lines.length === drafted.length &&
        q.lines.every((l, i) => l.catalogueId === drafted[i].catalogueId && l.rate === drafted[i].rate) &&
        q.total === write.response.total &&
        q.total === 12000 + 28500
      );
    },
    describe,
  },
  {
    checkId: "log-survives",
    // 9. The log survives
    //
    // Conformance:  The source job, the price-list lines used, the draft and the outcome are retained together and retrievable by quote_id.
    // Inject:       Any completed draft, then a retrieval by quote_id.
    // Then assert:  One quote_id returns the source job, the ordered port calls, the catalogue ids used and the outcome as one object.
    // On the stub:  The stub proves the parts are tied together and retrievable. Retention is a property of where it is stored rather than of the build.
    world: () => new QuoteWorld({ jobs: [{ id: "JOB-901", source: "form", wants: ["PL-TAP-REWASHER", "PL-CALLOUT"] }], pricebook: BOOK }),
    drive: (build, world) => build(world.ports(), jobCreated("JOB-901")),
    holds: (world) => {
      const id = creates(world)[0]?.response?.id;
      const d = id ? world.dossier(id) : null;
      if (!d) return false;
      const order = d.calls.map((c) => c.port);
      const iJob = order.indexOf("read_job");
      const iBook = order.indexOf("read_pricebook");
      const iDraft = order.indexOf("draft_quote");
      return (
        d.job?.id === "JOB-901" &&
        d.quote.state === "draft" &&
        d.catalogueIds.join(",") === "PL-TAP-REWASHER,PL-CALLOUT" &&
        iJob >= 0 && iJob < iBook && iBook < iDraft
      );
    },
    describe,
  },
  {
    checkId: "pricebook-is-current",
    // 10. The price list was read, not remembered
    //
    // Conformance:  Rates are read from the live price list at draft time. A cached copy older than the agreed window parks the quote rather than pricing it.
    // Inject:       A draft raised after the price list has changed in the system of record.
    // Then assert:  The read returns the changed rate and the draft carries it, or the quote parks. The superseded rate appears nowhere on the draft.
    // On the stub:  The stub proves the build reads at draft time rather than from a cache of its own. Only a live tenant proves the vendor's API returns the rate the office believes is current.
    world: () =>
      new QuoteWorld({
        jobs: [
          { id: "JOB-1001", source: "call", wants: ["PL-CALLOUT"] },
          { id: "JOB-1002", source: "call", wants: ["PL-CALLOUT"] },
        ],
        pricebook: BOOK,
      }),
    drive: async (build, world) => {
      // A first job warms any cache a build might keep. Then the office puts through an increase.
      await build(world.ports(), jobCreated("JOB-1001"));
      world.advance(60 * 60_000);
      world.changePrice("PL-CALLOUT", 13500);
      await build(world.ports(), jobCreated("JOB-1002"));
    },
    holds: (world) => {
      const second = creates(world).find((c) => c.request.jobId === "JOB-1002");
      const reads = calls(world, "read_pricebook");
      if (!second) return false;
      const readBefore = reads.some((r) => world.calls.indexOf(r) < world.calls.indexOf(second) && world.calls.indexOf(r) > world.calls.indexOf(creates(world)[0]));
      const rates = second.request.lines.map((l) => l.rate);
      return readBefore && rates.includes(13500) && !rates.includes(12000) && world.quotes.find((q) => q.jobId === "JOB-1002")?.total === 13500;
    },
    describe,
  },
];

// The checks a stub cannot pass, and is not asked to. These run only in
// production (AIPATHWAY_ENV=production), against your own systems or the
// hosted provider. Check 11 is the step the standard says not to hand-roll:
// on the stub it reports with_us. Its holds is written so that, when it does
// run live, it asserts the three runs the standard names and nothing less.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 11. The pass test passes
    //
    // Conformance:  One real job, staged on the real system of record, drafted against the real price list, including a line the book does not cover.
    // Inject:       A real job, from a ServiceM8 or Simpro tenant or held by the build when the books are in Xero alone, run once with a line not in the price list and then twice without it.
    // Then assert:  Run 1 wrote nothing and parked with not_in_pricebook, carrying the priced lines, no total and no invented rate. Run 2 left one real draft quote in that tenant against real catalogue ids. Run 3 kept that quote rather than creating a second, carrying duplicate_of.
    // On the stub:  Deliberately unpassable on a stub. A stub cannot authenticate into a tenant it does not have, cannot be rejected by that vendor's validation, and cannot prove the catalogue ids it used are the ones the office actually bills on. This is the step the standard says not to hand-roll.
    world: () => new QuoteWorld(),
    drive: async (build, world) => {
      const jobId = process.env.QUOTE_DESK_LIVE_JOB_ID;
      world.outcomes = [];
      world.outcomes.push(await build(world.ports(), jobCreated(jobId)));
      // Between run 1 and run 2 a person drops the off-book line on the real job. The run waits on that.
      world.outcomes.push(await build(world.ports(), { name: "job.updated", job_id: jobId }));
      world.outcomes.push(await build(world.ports(), { name: "job.updated", job_id: jobId }));
    },
    holds: (world) => {
      const [r1, r2, r3] = world.outcomes ?? [];
      return (
        r1?.outcome === "parked" && r1.park_reason === "not_in_pricebook" && r1.total_ex_gst === null && (r1.lines?.length ?? 0) > 0 &&
        r2?.outcome === "drafted" && Boolean(r2.external_id) &&
        r3?.outcome === "kept" && r3.quote_id === r2.quote_id && r3.duplicate_of === r2.quote_id
      );
    },
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
